package com.goaltracker;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class Requirement
{
	private String name;
	private boolean blocked;
	private boolean completed;

	public void cycleState() {
		if (blocked) {
			blocked = false;
			completed = false;
		} else if (completed) {
			blocked = true;
			completed = false;
		} else {
			completed = true;
		}
	}
}

